aerospike_config:
# Single-node Community Edition benchmark instance. The raw namespace device
# is one partition of a six-NVMe RAID0; Keylane owns the sibling partition.
service {
	proto-fd-max 15000
	cluster-name ycsb-ce
}

logging {
	file /mnt/dev/aerospike-ycsb-rerun.log {
		context any info
	}
}

network {
	service {
		address any
		access-address 172.16.0.4
		port 3000
	}

	heartbeat {
		mode mesh
		port 3002
		interval 150
		timeout 10
	}

	fabric {
		address 172.16.0.4
		port 3001
	}

	admin {
		address 172.16.0.4
		port 3003
	}
}

namespace ycsb {
	replication-factor 1
	default-ttl 0
	indexes-memory-budget 64G
	stop-writes-sys-memory-pct 90

	storage-engine device {
		device /dev/md0p2
		flush-size 128K
		max-write-cache 8G
		stop-writes-used-pct 90
		stop-writes-avail-pct 5
	}
}

mod-lua {
	allow-unsafe-lua false
}
